// Take first 5 story IDs and prep for individual fetches
const ids = $input.first().json;
if (!Array.isArray(ids)) {
  throw new Error('HN API did not return an array. Response: ' + JSON.stringify(ids));
}
const top5 = ids.slice(0, 5);
return top5.map(id => ({ json: { id } }));

// Label hot stories and format for digest
const items = $input.all();
return items.map(item => ({
  json: {
    label: '🔥 HOT',
    title: item.json.title || '(no title)',
    score: item.json.score || 0,
    url: item.json.url || `https://news.ycombinator.com/item?id=${item.json.id}`,
    author: item.json.by || 'unknown',
    comments: item.json.descendants || 0
  }
}));

// Label trending stories
const items = $input.all();
return items.map(item => ({
  json: {
    label: '📈 TRENDING',
    title: item.json.title || '(no title)',
    score: item.json.score || 0,
    url: item.json.url || `https://news.ycombinator.com/item?id=${item.json.id}`,
    author: item.json.by || 'unknown',
    comments: item.json.descendants || 0
  }
}));

// Merge all labelled stories and build the digest message
const allStories = $input.all();

const lines = allStories.map((item, i) => {
  const d = item.json;
  return `${i + 1}. ${d.label} — *${d.title}*\n   Score: ${d.score} pts | By: ${d.author} | Comments: ${d.comments}\n   ${d.url}`;
}).join('\n\n');

const now = new Date().toUTCString();
const message = `📰 *HackerNews Morning Brief*\n_${now}_\n\n${lines}\n\n— Powered by n8n automation`;

return [{ json: { message } }];

// Error handler — log details and surface for investigation
const errorData = $input.first().json;
const errorMessage = [
  '⚠️ n8n Workflow Error — Morning Brief',
  `Time: ${new Date().toUTCString()}`,
  `Node: ${errorData.execution?.lastNodeExecuted || 'unknown'}`,
  `Error: ${errorData.execution?.error?.message || JSON.stringify(errorData)}`,
  'Check your n8n execution log for full details.'
].join('\n');
console.error(errorMessage);
return [{ json: { errorMessage, timestamp: new Date().toISOString() } }];
